import * as T from 'three';
import {animateAstronaut} from './moon-astronaut.mjs';
import {vipFlight} from './moon-vip-visit.mjs';
export function createVipPresentation(model,plan,root){
 const group=new T.Group();group.name='VIP party and ceremony';root.add(group);const people=[],animations=[];
 for(let i=0;i<5;i++){const body=model('ME-008'),animation=animateAstronaut(body,{name:i===0?'You':i===1?'Your companion':'VIP retinue',persona:'Spacesuited visitor',offset:i});if(i<2){const regalia=model('RE-078');regalia.position.set(0,1.1,.20);body.add(regalia);}group.add(body);people.push(body);animations.push(animation);}
 const banner=model('RE-077');group.add(banner);const cameraLocal=new T.Vector3();banner.traverse(o=>{if(o.isMesh)o.onBeforeRender=(renderer,scene,camera)=>{camera.getWorldPosition(cameraLocal);group.worldToLocal(cameraLocal);banner.rotation.y=Math.atan2(cameraLocal.x-banner.position.x,cameraLocal.z-banner.position.z);};});
 const bursts=[];for(let i=0;i<4;i++){const burst=model('RE-079');burst.traverse(o=>{if(o.isMesh){o.material=o.material.clone();o.material.transparent=true;o.material.depthWrite=false;}});group.add(burst);bursts.push(burst);}
 function pose(body,seated,waving,t,i){let rig;body.traverse(o=>{if(o.isBone&&o.name==='suit-root')rig=o;});if(!rig)return;const [left,right,armL,armR]=rig.children;armL.rotation.z=armR.rotation.z=0;if(seated){left.rotation.x=right.rotation.x=-Math.PI/2;left.children[0].rotation.x=right.children[0].rotation.x=Math.PI/2;armL.rotation.x=armR.rotation.x=-1.1;}else if(waving){armR.rotation.z=-2.25+Math.sin(t*5+i)*.22;armR.rotation.x=.2;}}
 return {group,update(state){const v=state.rocket.vip;group.visible=!!v&&v.phase!=='home';if(!group.visible)return;const f=vipFlight(state),inShip=['waiting-for-pad','descending','ascending'].includes(v.phase);group.visible=f.phase!=='in-transit';for(let i=0;i<people.length;i++){const body=people[i],p=v.people[i];body.position.set(p.position.x,p.position.y+(inShip?f.altitude:0),p.position.z);body.rotation.set(0,p.seated?(i<2?0:i===3?-Math.PI/2:Math.PI/2):p.heading,0);animations[i].update(state.seconds,p.moving,false,p.name);pose(body,p.seated,v.phase==='celebrating'||v.phase==='tour-stop',state.seconds,i);body.userData.inspect={title:p.name,kind:p.role==='VIP'?'VIP guest · spacesuit':'VIP retinue · spacesuit',description:p.role==='VIP'?'Travelling aboard USS AURORA for a ceremonial base visit.':'Accompanies the VIP guests through the base and home.'};body.userData.vipId=p.id;body.userData.activity=v.phase;body.userData.liveReadout=()=>`${v.phase} · ${v.stops[v.stop]?.label??'Aurora'} · homebound after the tour`;}
 const leader=v.people[0];banner.visible=['greeting','celebrating','touring','tour-stop','returning'].includes(v.phase);banner.position.set(leader.position.x,leader.position.y+2.65+Math.sin(state.seconds*1.5)*.07,leader.position.z);
 for(let i=0;i<bursts.length;i++){const burst=bursts[i],age=(state.seconds-v.phaseStarted-i*.9)%3.6;burst.visible=v.phase==='celebrating'&&age>=0&&age<2.7;const q=Math.max(0,age/2.7);burst.position.set(leader.position.x+(i%2?4:-4),leader.position.y+4+(i%2),leader.position.z+(i<2?-3:3));burst.scale.setScalar(.2+q*1.8);burst.rotation.y=i+age*.1;burst.traverse(o=>{if(o.isMesh)o.material.opacity=Math.max(0,1-q);});}
 },dispose(){for(const a of animations)a.dispose();for(const b of bursts)b.traverse(o=>{if(o.isMesh)o.material.dispose();});root.remove(group);}};
}
